import { digest, includes, keyOf, readBytes, relativeName } from "./policy.mjs";
import { citation, lineList } from "./preflight.mjs";

/** Enumerate explicit factual rows as well as the project's required minimum. */
export function expectedClaims(spec, lines) {
  const discovered = lines.flatMap(line => {
    const match = /^\s*(?:[-*]\s+|\d+[.)]\s+)?(?:\*\*)?(C\d+)(?:\*\*)?\s*[:：]/.exec(line);
    return match ? [match[1]] : [];
  });
  return [...new Set([...spec.claims, ...discovered])];
}

/** Validate a source against actual reads, current bytes and an optional origin pin. */
export function evidenceReference(frame, active, spec, input) {
  const file = relativeName(input?.file);
  const grant = spec.phases[active.phase];
  if (!includes(grant.evidence, file)) throw new Error("资料引用不在本轮证据授权中 " + file);
  const bytes = readBytes(frame.root, file);
  const seen = active.seen[keyOf(file)];
  const { start, end } = input;
  if (!bytes || !Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start < 1 || end < start
    || end > lineList(bytes).length || seen?.hash !== digest(bytes)
    || !seen.ranges.some(([a, b]) => a <= start && b >= end)) {
    throw new Error("资料引用须对应本轮实际读过的当前原文行 " + file);
  }
  const sha256 = digest(bytes);
  const pin = frame.policy.sourcePins[keyOf(file)];
  if (spec.requireSourcePins && !pin) throw new Error("资料缺少项目维护者登记的来源凭据 " + file);
  if (pin && pin.sha256 !== sha256) throw new Error("资料与登记的原始版本不符，须重新核验来源 " + file);
  return { file, start, end, sha256, origin: pin
    ? { kind: pin.kind, locator: pin.locator, integrity: "matches-pin" }
    : { kind: "unregistered", integrity: "observed-local-bytes" } };
}

/** Build the read inventory from the host's coverage records, never model prose. */
export function readInventory(frame, active) {
  return frame.reads.flatMap(file => {
    const observed = active.seen[keyOf(file)];
    const bytes = observed && readBytes(frame.root, file);
    return observed ? [{ file, sha256: observed.hash, ranges: observed.ranges, current: !!bytes && digest(bytes) === observed.hash }] : [];
  });
}

/** Reject the earlier false-read case even when it is hidden in a source narrative. */
export function checkSourceNarrative(frame, active, note) {
  const candidates = new Set([
    ...frame.policy.coordinator.read, ...frame.policy.instructions,
    ...Object.values(frame.policy.units).flatMap(unit => Object.values(unit.phases).flatMap(phase => phase.read)),
    ...(note.match(/[\p{L}\p{N}_.@-]+(?:\/[\p{L}\p{N}_.@-]+)+\.(?:md|json|csv|txt|yml|yaml|mjs|js|py)\b/gu) ?? []),
  ]);
  for (const file of candidates) {
    if (!citation(note, file)) continue;
    const seen = active.seen[keyOf(file)];
    const bytes = includes(frame.reads, file) && readBytes(frame.root, file);
    if (!bytes || seen?.hash !== digest(bytes)) {
      throw new Error("资料说明提及本轮未实际读取的文件 " + file + "，请读取后再判断，或改在 unverifiedSources 中记录");
    }
  }
}

/** Store unresolved factual prose as exact candidate-line findings for supplement. */
export function coverageFindings(value, lines) {
  if (!Array.isArray(value) || value.length > 64) throw new Error("请用 unlisted 列出未编号、仍需核验的事实行，完成覆盖核对时填 []");
  return value.map(item => {
    if (!Number.isSafeInteger(item?.line) || item.line < 1 || item.line > lines.length
      || typeof item.basis !== "string" || !item.basis.trim() || item.basis.length > 1200) throw new Error("未登记事实须给候选行号及原因");
    return { line: item.line, basis: item.basis.trim(), text: lines[item.line - 1] };
  });
}

import { digest, keyOf, readBytes } from "./policy.mjs";
import { lineList } from "./preflight.mjs";

/** Bind acceptance to explicit central files; hashes identify versions, not truth. */
export function goalSnapshot(frame) {
  if (!frame.policy.goalContext.length) throw new Error("请在 goalContext 或 ledgerContext 配置项目目标文件");
  const files = frame.policy.goalContext.map(file => {
    const bytes = readBytes(frame.root, file);
    if (!bytes) throw new Error("项目目标文件不存在 " + file);
    return { file, sha256: digest(bytes) };
  });
  return { sha256: digest(JSON.stringify(files)), files };
}

/** Every review sees the current goal in addition to the unchanged factual evidence. */
export function requireGoalRead(frame, active, refresh = false) {
  const current = goalSnapshot(frame);
  if (!refresh && active.goal?.sha256 !== current.sha256) throw new Error("项目目标已变，请总控 advance 重启当前目标的独立验收");
  for (const { file, sha256 } of current.files) {
    const seen = active.seen?.[keyOf(file)];
    const length = lineList(readBytes(frame.root, file)).length;
    if (seen?.hash !== sha256 || !seen.ranges.some(([a,b]) => a === 1 && b >= length)) {
      throw new Error("验收前须完整读取当前目标 " + file);
    }
  }
  // Executors can acknowledge a goal changed during their work after reading it;
  // reviewers must start a new independent checkpoint to avoid mixed-version receipts.
  if (refresh) active.goal = current;
  return current;
}

/** A changed goal, candidate or receipt invalidates closure, even after an earlier close. */
export function acceptedVersion(frame, id, active) {
  const bytes = readBytes(frame.root, active.receipt);
  if (!bytes || digest(bytes) !== active.receiptHash) throw new Error("验收回执在账本复核前发生变化，停止关单并核实");
  const receipt = JSON.parse(bytes.toString("utf8"));
  const current = goalSnapshot(frame);
  if (receipt.goal?.sha256 !== current.sha256 || receipt.goalFit?.pass !== true) {
    throw new Error("验收未覆盖当前目标，请总控 advance 重新独立验收；原事实证据保留");
  }
  const candidate = readBytes(frame.root, frame.policy.units[id].candidate);
  if (!candidate || receipt.candidateSha256 !== digest(candidate) || receipt.decision !== "accept") {
    throw new Error("当前候选与通过回执不一致，请总控 advance 重新独立验收");
  }
  return receipt;
}

/** Permit revalidation without granting the coordinator access to module contents. */
export function needsRevalidation(frame, id, active) {
  if (!active) return false;
  // Old rejected fingerprints cannot describe text after a citation. Rebuild them
  // through the independent reviewer, never by treating the edited draft as baseline.
  if (["supplement-ready","supplement","blocked"].includes(active.phase)
    && active.unsupported?.some(claim => active.rejected?.[claim]?.version !== 2)) return true;
  if (["ledger-review", "closed"].includes(active.phase)) {
    try { acceptedVersion(frame, id, active); return false; } catch { return true; }
  }
  return ["first-review", "final-review", "goal-review-ready"].includes(active.phase)
    && active.goal?.sha256 !== goalSnapshot(frame).sha256;
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import {
  AUTHORITY, MANAGED, PHASES, authority, digest, includes, keyOf, readBytes, relativeName, replaceBytes,
  replaceWithHistory, text, workspaceRoot,
} from "./policy.mjs";
import {
  QUALITY, citation, claimRow, deliveryQuality, lineList, numericChecks,
  rejectedClaims, reviewedQuality, supplementChecks,
} from "./preflight.mjs";
import { checkSourceNarrative, coverageFindings, evidenceReference, expectedClaims, readInventory } from "./evidence.mjs";
import { TERMINAL, beginLedgerReview, captureRequest, ledgerAction, ledgerSummary, noteContextRead, trackUnit } from "./ledger.mjs";
import { goalSnapshot, needsRevalidation, requireGoalRead } from "./goals.mjs";

export const name = "building-loop-governance";
export const inject = ["agents", "subagents", "systemPrompt", "tools"];
const WORKFLOW = "building_loop";
const FILE = "building_loop_file";
const ASSESS = "building_loop_quality";
const LEDGER = "building_loop_ledger";
const EMPTY = { read: [], write: [] };

const BEGIN = {
  dispatch: "intake",
  "review-ready": "first-review",
  "supplement-ready": "supplement",
  "final-review-ready": "final-review",
  "goal-review-ready": "final-review",
};

const RULES = {
  intake: "接单。按指定二级索引找到候选，第一轮按任务单保留原稿送审。读回候选后用 submit 交接。来源真伪由独立核验方查，接单阶段缺少来源读权不构成阻塞。仅候选缺失或明确无法执行的任务才 block。宿主通知总控。",
  "first-review": "首次验收。独立打开候选和每条引用的原文，核数字、行号和适用范围。无出处或原文不支持就填 unsupported，不代为补查。",
  supplement: "补查。先读当前目标和退回回执，旧派单与新目标冲突时以当前目标为准。用 preflight 获取待改项，按原始证据原位修订，保留编号，出处路径和原文行写在同一行，例如 第 2-3 行。勿把内部修订说明混入成稿。完整读回后 submit 带六项 quality。未读当前目标、未落实退回项或复算不符会被拦住。",
  "final-review": "终审。回到修订稿和原始证据，重新核对所有断言与改动。只有所有要求都支持才关单。",
};
const REVIEW_FORMAT = '先完整读当前目标文件、候选和引用原文。事实与写法分别判定：有据的事实应 supported，禁止因可选解释、排版或材料未提供的精度判 unsupported。事实退回须 finding={kind:"missing-evidence"|"contradiction"|"scope",quote:候选中实际存在的原句片段,fix:最小修正}；contradiction 还须 file/start/end 指向已读反证。不要要求补写原稿没有的新事实。事实支持后用 building_loop_quality assess：六项短依据、sourceRefs(file/start/end)、unverifiedSources、unlisted(line/basis)、revise；goalFit={pass,basis}明确现稿是否满足当前目标，符合便可通过，无需为“修订”而改字。质量退回须 revisions=[{field,change,requirement:{file,start,end}}]引用实际读取的目标或项目规则；可选改进放 suggestions，不阻止验收。最后 review 逐条 checks，支持项填 id/status="supported"/file/start/end/basis。空列表填 []。';
const QUALITY_RULE = "质量说明按任务规模写，小任务每项一两句具体内容。资料标实际来源及未证事项，结论和方法交代边界与取舍，给一个可行备选，先摘要后证据并留一句大白话。必要时引用文件和行号，细节留在正文，回执不用重复全文或哈希。";
const COORDINATOR = {
  dispatch: "派单。确认任务、单元与范围，advance 签发接单。",
  "review-ready": "接单方已交付。advance 发起首次独立核验。",
  "supplement-ready": "核验退回。依据回执用 advance 发起补查，默认续用执行会话。",
  "final-review-ready": "补查已交付。advance 发起终审。",
  "goal-review-ready": "目标已改变或旧验收版本失效。advance 续用核验会话验证当前交付，原事实记录保留。",
  blocked: "先确认解阻条件，再用 advance 恢复原阶段和原子会话。模型首次中断可以续派，反复中断则把实际阻塞记入台账。",
  "ledger-review": "本轮事实已验收。必须用 building_loop_ledger 的 read 读最新账本，并读取授权的项目现状文件和本轮验收回执。结合当前目标、变更和已有成果，对每条未结事项决定 keep/resume/defer/completed/covered/obsolete，说明原因。完成、被覆盖或失效须附当前原文行依据。用账本 review 关单，保留和续做均由现状判断。",
  closed: "单元已验收关单。读通过回执、核对执行身份并更新授权台账。汇报先给结论，再按需展开出处、方法、备选和未证边界，最后一句大白话。",
};

const string = { type: "string" };
const number = { type: "integer" };
const isReview = phase => phase.endsWith("review");
const buffer = value => Buffer.from(JSON.stringify(value, null, 2) + "\n", "utf8");

/** 统一 DSH 工具契约，所有变更按非并发工具串行提交。 */
function tool(name, description, action, properties, execute, required = []) {
  return {
    name, description,
    parameters: {
      type: "object",
      properties: { action: { type: "string", enum: action }, ...properties },
      required: ["action", ...required],
      additionalProperties: false,
    },
    output: {
      schema: { type: "object" },
      render: (_args, result) => [{ type: "text", text: JSON.stringify(result) }],
    },
    isConcurrencySafe: () => false,
    async execute(args, exec) {
      return JSON.parse(JSON.stringify(await execute(args, exec)));
    },
  };
}

/** 限制交接说明的大小并拒绝空理由。 */
function requireText(value, label, limit = 1200) {
  if (typeof value !== "string" || !value.trim() || value.length > limit) throw new Error("需要" + label);
  return value.trim();
}

/** 从已解析的授权清单取单元，防止模型自创越权单元。 */
function unitOf(frame, id) {
  if (!Object.hasOwn(frame.policy.units, id)) throw new Error("该工作单元未获授权");
  return frame.policy.units[id];
}

/** 向总控只暴露阶段、身份和回执入口，正文仍走文件授权。 */
function viewUnits(frame) {
  return Object.keys(frame.policy.units).map(id => {
    const unit = Object.hasOwn(frame.state.units, id) ? frame.state.units[id] : undefined;
    if (!unit) return { unit: id, phase: "dispatch", next: "intake" };
    const { phase, executor, reviewer, receipt, unsupported, qualityRejected, blocked, interruptions } = unit;
    return {
      unit: id, phase, executor, reviewer, receipt, unsupported, qualityRejected, blocked, interruptions,
      next: needsRevalidation(frame, id, unit) ? "final-review" : phase === "blocked" ? unit.resumePhase : BEGIN[phase],
      goalStale: needsRevalidation(frame, id, unit),
      owned: unit.owner === frame.agent.id,
    };
  });
}

/** 安装预设内的工具、强制注入和事件记录，普通模式独立运行。 */
export function apply(ctx, config = {}) {
  const presetId = config.presetId ?? "building-loop";
  const hostHome = path.resolve(process.env.DSH_HOME || path.join(os.homedir(), ".dsh"));
  const stateHome = path.join(hostHome, "building-loop-state");
  fs.mkdirSync(stateHome, { recursive: true });

  /** 每次操作重新读取清单和持久状态，以真实父子会话确定权限。 */
  function scope(agent) {
    if (!agent || ctx.agents.get(agent.id) !== agent) throw new Error("只接受当前 DSH 会话的调用");
    const root = workspaceRoot(agent.session.header.cwd, hostHome);
    const policy = authority(root);
    const file = digest(keyOf(root)) + ".json";
    const old = readBytes(stateHome, file);
    let state = old ? JSON.parse(text(old)) : { spec: "building-loop-state/1", policy: policy.hash, units: {}, markers: {} };
    if (state.spec !== "building-loop-state/1") throw new Error("工作台账版本无效");
    if (state.policy !== policy.hash) {
      if (Object.values(state.units).some(unit => !TERMINAL.has(unit.phase))) throw new Error("运行期间授权清单发生变化，需项目维护者核对");
      state = { ...state, policy: policy.hash, units: {} };
    }
    state.units = Object.assign(Object.create(null), state.units);
    state.markers = Object.assign(Object.create(null), state.markers);
    const parent = agent.session.header.parentSession;
    const child = parent !== undefined || agent.session.header.origin === "subagent";
    let assignment;
    if (child) {
      assignment = Object.entries(state.units).find(([, unit]) =>
        unit.owner === parent && unit.actor === agent.id && PHASES.includes(unit.phase));
    }
    const role = child ? !assignment ? "idle" : isReview(assignment[1].phase) ? "reviewer" : "executor" : "coordinator";
    const grant = assignment ? unitOf({ policy }, assignment[0]).phases[assignment[1].phase] : child ? EMPTY : policy.coordinator;
    // goalContext explicitly grants read-only central context to working roles.
    const reads = role === "idle" ? [] : [...new Set([...grant.read, ...policy.instructions, ...policy.goalContext])];
    return { agent, root, policy, file, old, state, role, assignment, reads, writes: grant.write };
  }

  /** 同工作区状态共用独占锁，操作成功后原子落盘。 */
  function change(agent, operation) {
    const info = scope(agent);
    const lock = path.join(stateHome, info.file + ".lock");
    let fd;
    try { fd = fs.openSync(lock, "wx", 0o600); }
    catch (error) {
      if (error.code === "EEXIST") throw new Error("工作台账正在更新，请按当前台账重试");
      throw error;
    }
    try {
      const frame = scope(agent);
      if (frame.file !== info.file) throw new Error("工作区在动作前发生变化");
      const result = operation(frame);
      if (frame.changed) {
        // Workflow and ledger share a rolling pre-edit snapshot as well as the lock.
        const backup = frame.file + ".bak";
        if (frame.old) replaceBytes(stateHome, backup, frame.old, readBytes(stateHome, backup));
        replaceBytes(stateHome, frame.file, buffer(frame.state), frame.old);
      }
      return result;
    } finally {
      fs.closeSync(fd);
      fs.unlinkSync(lock);
    }
  }

  /** 同阶段重试沿用改前备份，跨阶段建立新的改前边界。 */
  function tag(frame) {
    if (frame.assignment) {
      const [id, unit] = frame.assignment;
      return unit.owner + "/" + id + "/" + unit.serial + "/" + unit.phase;
    }
    return frame.agent.id + "/coordinator/" + Object.values(frame.state.units)
      .map(unit => unit.serial + "-" + unit.phase).join("_");
  }

  /** 文件入口集中执行白名单、实际已读行记录、日志和滚动备份。 */
  function fileAction(args, exec) {
    return change(exec.agent, frame => {
      if (frame.role === "idle") throw new Error("当前子会话没有已授权的工作阶段");
      if (args.action === "list") return { read: frame.reads, write: frame.writes };
      if (args.action === "search") {
        const query = requireText(args.query, "搜索字面量", 120);
        const paths = args.path === undefined ? frame.reads : [relativeName(args.path)];
        const matches = [];
        for (const file of paths) {
          if (!includes(frame.reads, file)) throw new Error("该文件不在当前读白名单");
          const bytes = readBytes(frame.root, file);
          if (!bytes) continue;
          const lines = lineList(bytes);
          for (let i = 0; i < lines.length && matches.length < 40; i++) {
            if (lines[i].includes(query)) matches.push({ path: file, line: i + 1, text: lines[i].slice(0, 800) });
          }
          if (matches.length >= 40) break;
        }
        return { matches };
      }
      const file = relativeName(args.path);
      if (args.action === "write") {
        if (!includes(frame.writes, file)) throw new Error("该文件不在当前写白名单");
        if (typeof args.content !== "string") throw new Error("需要 UTF-8 正文");
        const note = requireText(args.note, "改动理由", 500);
        const result = replaceWithHistory(frame.root, file, args.content, note, tag(frame), frame.state.markers);
        frame.changed = result.changed;
        return result;
      }
      if (!includes(frame.reads, file)) throw new Error("该文件不在当前读白名单");
      if (args.action === "history") {
        const history = readBytes(frame.root, MANAGED + "/changes/" + file + ".md");
        return { path: file, recent: history ? lineList(history).slice(0, 12) : [] };
      }
      if (args.action !== "read") throw new Error("未知文件动作");
      const bytes = readBytes(frame.root, file);
      if (!bytes) throw new Error("授权文件目前不存在");
      const lines = lineList(bytes);
      const start = args.start ?? 1;
      const count = args.count ?? 150;
      if (!Number.isSafeInteger(start) || start < 1 || !Number.isSafeInteger(count) || count < 1 || count > 250) {
        throw new Error("行范围无效，单次最多 250 行");
      }
      if (frame.assignment && start <= lines.length) {
        const active = frame.assignment[1];
        const key = keyOf(file);
        const hash = digest(bytes);
        const coverage = Object.hasOwn(active.seen, key) ? active.seen[key] : undefined;
        const ranges = coverage?.hash === hash ? coverage.ranges : [];
        const end = Math.min(start + count - 1, lines.length);
        Object.defineProperty(active.seen, key, { value: { hash, ranges: mergeRanges([...ranges, [start, end]]) },
          configurable: true, enumerable: true, writable: true });
        frame.changed = true;
      }
      noteContextRead(frame, file, digest(bytes), start, Math.min(start + count - 1, lines.length));
      return { path: file, totalLines: lines.length, sha256: digest(bytes),
        lines: lines.slice(start - 1, start - 1 + count).map((line, index) => [start + index, line]) };
    });
  }

  /** 只允许拥有该单元的总控推进，阻塞单元可保留待后续处理。 */
  function prepare(frame, id) {
    if (frame.role !== "coordinator") throw new Error("只有总控可以推进阶段");
    const spec = unitOf(frame, id);
    const prior = Object.hasOwn(frame.state.units, id) ? frame.state.units[id] : null;
    if (prior && prior.owner !== frame.agent.id) throw new Error("此工作单元由其他总控持有");
    if (Object.entries(frame.state.units).some(([key, unit]) => key !== id && !TERMINAL.has(unit.phase) && unit.phase !== "blocked")) {
      throw new Error("当前工作区另有未结单的单元");
    }
    const revalidating = needsRevalidation(frame, id, prior);
    const phase = revalidating ? "final-review"
      : prior?.phase === "blocked" ? prior.resumePhase : BEGIN[prior?.phase ?? "dispatch"];
    if (!phase) throw new Error("当前阶段尚未交付或已经关单");
    const role = isReview(phase) ? "reviewer" : "executor";
    const reusable = revalidating ? prior?.reviewer : prior?.phase === "blocked" ? prior.actor
      : phase === "supplement" && spec.continuation === "fresh" ? undefined : prior?.[role];
    return { prior, phase, role, reusable, serial: (prior?.serial ?? 0) + 1 };
  }

  /** 先绑定阶段和执行身份再唤醒子会话，派发失败恢复原状态。 */
  async function advance(args, exec) {
    const agent = exec.agent;
    const id = args.unit;
    const prepared = prepare(scope(agent), id);
    const resident = prepared.reusable && ctx.agents.get(prepared.reusable);
    if (resident) await waitIdle(resident, exec.signal);
    exec.signal.throwIfAborted();
    const childId = prepared.reusable ?? randomUUID();
    const next = change(agent, frame => {
      const plan = prepare(frame, id);
      if (plan.phase !== prepared.phase || plan.serial !== prepared.serial || plan.reusable !== prepared.reusable) {
        throw new Error("工作单元已经由其他调用推进");
      }
      const record = {
        ...(plan.prior ?? {}), owner: agent.id, actor: childId, [plan.role]: childId,
        phase: plan.phase, serial: plan.serial, seen: {}, goal: goalSnapshot(frame),
      };
      delete record.blocked;
      delete record.resumePhase;
      delete record.assessment;
      if (plan.prior?.phase !== "blocked") delete record.interruptions;
      const spec = unitOf(frame, id);
      if (plan.phase === "supplement" && record.unsupported?.length && !record.rejected) {
        const candidate = readBytes(frame.root, spec.candidate);
        if (!candidate) throw new Error("无法为旧退回记录建立候选基线");
        record.rejected = rejectedClaims(frame.root, spec, lineList(candidate),
          record.unsupported.map(id => ({ id })), spec.phases.supplement.read);
      }
      frame.state.units[id] = record;
      trackUnit(frame, id, record);
      frame.changed = true;
      const brief = "工作单元 " + id + " 进入 " + plan.phase + "。候选文件 " + spec.candidate
        + (record.receipt && plan.phase === "supplement" ? "。请读取退回回执 " + record.receipt : "")
        + "。执行前依据已注入的阶段规则与授权范围。"
        + (args.note === undefined ? "" : "\n本次任务要求 " + requireText(args.note, "任务说明"));
      return { workspace: frame.root, phase: plan.phase, serial: plan.serial, brief };
    });
    const content = [{ type: "text", text: next.brief }];
    try {
      if (prepared.reusable) {
        await ctx.subagents.sendMessage(agent, childId, content, { signal: exec.signal });
      } else {
        const selection = agent.model.current();
        await ctx.subagents.startActivation({
          provider: "spawn", childId, label: id + " " + next.phase,
          delivery: "parent", signal: exec.signal,
          request: {
            parent: agent, cwd: next.workspace, agentPreset: presetId, prompt: content, maxDepth: 1,
            ...(selection ? { agentOptions: selection } : {}),
          },
        });
      }
    } catch (error) {
      change(agent, frame => {
        const record = frame.state.units[id];
        if (record?.actor === childId && record.phase === next.phase && record.serial === next.serial) {
          if (prepared.prior) frame.state.units[id] = prepared.prior;
          else delete frame.state.units[id];
          frame.changed = true;
        }
      });
      throw error;
    }
    return { unit: id, phase: next.phase, childId, reused: Boolean(prepared.reusable) };
  }

  /** 中断保留原阶段，恢复时续回同一个子会话。 */
  function pause(active, reason) {
    active.blocked = reason;
    active.resumePhase = active.phase;
    active.phase = "blocked";
  }

  /** 独立核验方提交判断，宿主核引用并绑定当前材料版本。 */
  function assess(args, exec) {
    return change(exec.agent, frame => {
      if (frame.role !== "reviewer" || frame.assignment[0] !== args.unit) {
        throw new Error("只有本单元的独立核验方可提交质量判断");
      }
      const [id, active] = frame.assignment;
      requireGoalRead(frame, active);
      const bytes = reviewCandidate(frame, active, unitOf(frame, id));
      const checks = reviewedQuality(args, args.revise);
      if (typeof args.goalFit?.pass !== "boolean") throw new Error("goalFit 须判断当前候选是否满足本轮目标");
      const goalFit = { pass: args.goalFit.pass, basis: requireText(args.goalFit.basis, "目标验收依据") };
      const revisions = validateRevisions(frame, active, args.revisions ?? [], args.revise);
      if (!goalFit.pass) checks.conclusion = { pass: false, basis: goalFit.basis };
      const spec = unitOf(frame, id);
      if (!Array.isArray(args.sourceRefs) || !args.sourceRefs.length || args.sourceRefs.length > 64) throw new Error("请逐份提交实际读取的 sourceRefs");
      const refs = args.sourceRefs.map(ref => evidenceReference(frame, active, spec, ref));
      checkSourceNarrative(frame, active, args.sources);
      if (!Array.isArray(args.unverifiedSources) || args.unverifiedSources.length > 64
        || args.unverifiedSources.some(item => typeof item !== "string" || !item.trim() || item.length > 1000)) throw new Error("请在 unverifiedSources 记录未核资料，空列表填 []");
      const unlisted = coverageFindings(args.unlisted, lineList(bytes));
      if (unlisted.length) checks.sources = { pass: false, basis: checks.sources.basis + "。候选存在未登记待核事实" };
      active.assessment = { hash: digest(bytes), checks, refs, unlisted, unverifiedSources: args.unverifiedSources,
        goalFit, revisions, suggestions: (args.suggestions ?? []).map(item => requireText(item,"可选建议")) };
      frame.changed = true;
      return { unit: id, assessed: true, observedSources: refs, actualReads: readInventory(frame, active),
        revise: Object.keys(checks).filter(field => !checks[field].pass), next: "review" };
    });
  }

  /** 验收回执由宿主写入，事实通过后还必须完成账本复盘。 */
  function report(args, exec) {
    return change(exec.agent, frame => {
      if (!frame.assignment) throw new Error("当前会话没有可交付阶段");
      const [id, active] = frame.assignment;
      if (args.unit !== id) throw new Error("当前会话无该单元的权限");
      const spec = unitOf(frame, id);
      if (frame.role === "reviewer" && active.goal?.sha256 !== goalSnapshot(frame).sha256) {
        active.phase = "goal-review-ready";
        active.seen = {};
        delete active.assessment;
        frame.changed = true;
        return { unit: id, phase: active.phase, parent: active.owner, reason: "目标变更，原验收停止，advance 重新验收当前目标" };
      }
      if (args.action === "block") {
        pause(active, requireText(args.note, "阻塞原因、责任人和恢复条件"));
        trackUnit(frame, id, active, true);
      } else if (args.action === "submit" && frame.role === "executor") {
        const bytes = readBytes(frame.root, spec.candidate);
        if (!bytes) throw new Error("候选文件尚未交付");
        const seen = active.seen[keyOf(spec.candidate)];
        if (seen?.hash !== digest(bytes) || !seen.ranges.some(([a, b]) => a === 1 && b >= lineList(bytes).length)) {
          throw new Error("请先完整读回当前候选文件");
        }
        if (active.phase === "supplement") {
          requireGoalRead(frame, active, true);
          const preflight = supplementChecks(frame.root, spec, lineList(bytes), frame.reads, active);
          if (!preflight.ok) throw new Error("[building-loop/preflight] " + preflight.issues.join("；"));
          if (active.qualityRejected?.length && active.rejectedCandidate === digest(bytes)) {
            throw new Error("质量退回须落实到候选正文，不能只重写提交说明");
          }
          active.quality = deliveryQuality(args.quality, active.quality, active.qualityRejected);
          active.phase = "final-review-ready";
        } else {
          active.phase = "review-ready";
        }
      } else if (args.action === "review" && frame.role === "reviewer") {
        requireGoalRead(frame, active);
        const grant = spec.phases[active.phase];
        const bytes = reviewCandidate(frame, active, spec);
        const lines = lineList(bytes);
        const hash = digest(bytes);
        let checked = reviewChecks(frame, active, spec, grant, args.checks, lines);
        // Evaluate each configured number even when another claim has already failed.
        const calculations = numericChecks(frame.root, spec, lines, frame.reads);
        const mismatches = new Map(calculations.filter(result => !result.ok).map(result => [result.id, result.issue]));
        checked = checked.map(check => mismatches.has(check.id)
          ? { ...check, status: "unsupported", basis: "脚本复算未通过 " + mismatches.get(check.id) } : check);
        const unsupported = checked.filter(check => check.status !== "supported").map(check => check.id);
        const qualityChecks = active.assessment?.hash === hash ? active.assessment.checks : null;
        if (!unsupported.length && !qualityChecks) throw new Error("请先用 building_loop_quality 提交当前候选的六项独立质量判断，再执行 review");
        const observedSources = qualityChecks ? active.assessment.refs?.map(ref => evidenceReference(frame, active, spec, ref)) : [];
        if (!unsupported.length && (!observedSources?.length || checked.some(check => !observedSources.some(ref =>
          keyOf(ref.file) === keyOf(check.file) && ref.sha256 === check.sha256 && ref.start <= check.end && ref.end >= check.start)))) {
          throw new Error("资料核验须覆盖每份支持结论的实际原文，请重新提交 sourceRefs");
        }
        const qualityRejected = qualityChecks ? Object.keys(qualityChecks).filter(field => !qualityChecks[field].pass) : [];
        const decision = unsupported.length || qualityRejected.length ? "reject" : "accept";
        active.rejected = rejectedClaims(frame.root, spec, lines, checked.filter(check => check.status !== "supported"), frame.reads);
        const receipt = {
          unit: id, phase: active.phase, reviewer: exec.agent.id, decision, candidateSha256: hash,
          goal: active.goal, goalFit: active.assessment?.goalFit,
          unsupported, qualityRejected, checks: checked, calculations,
          ...(active.quality ? { quality: active.quality } : {}),
          ...(qualityChecks ? { qualityChecks } : {}),
          observedSources, actualReads: readInventory(frame, active),
          ...(qualityChecks ? { unlisted: active.assessment.unlisted, unverifiedSources: active.assessment.unverifiedSources,
            revisions: active.assessment.revisions, suggestions: active.assessment.suggestions } : {}),
        };
        const receiptBytes = buffer(receipt);
        replaceWithHistory(frame.root, grant.receipt, text(receiptBytes), "独立核验 " + decision,
          tag(frame), frame.state.markers);
        active.receipt = grant.receipt;
        active.unsupported = unsupported;
        active.qualityRejected = qualityRejected;
        active.rejectedCandidate = decision === "reject" ? hash : null;
        active.unlisted = qualityChecks ? active.assessment.unlisted : [];
        active.phase = "supplement-ready";
        if (decision === "accept") beginLedgerReview(frame, id, active, receiptBytes);
        delete active.assessment;
        if (decision === "accept") delete active.quality;
      } else {
        throw new Error("当前角色和阶段不允许此动作");
      }
      active.seen = {};
      frame.changed = true;
      return { unit: id, phase: active.phase, receipt: active.receipt, unsupported: active.unsupported,
        qualityRejected: active.qualityRejected, parent: active.owner };
    });
  }

  /** 阶段动作统一入口，持久回执成功后再通知父会话。 */
  async function workflow(args, exec) {
    if (args.action === "status") {
      try {
        const frame = scope(exec.agent);
        if (frame.role === "coordinator") return { role: frame.role, units: viewUnits(frame), read: frame.reads, write: frame.writes };
        const assignment = frame.assignment;
        return { role: frame.role, unit: assignment?.[0], phase: assignment?.[1].phase, read: frame.reads, write: frame.writes };
      } catch (error) { return { blocked: String(error.message) }; }
    }
    if (args.action === "advance") return advance(args, exec);
    if (args.action === "preflight") {
      const frame = scope(exec.agent);
      const assignment = frame.assignment;
      if (!assignment || args.unit !== assignment[0] || assignment[1].phase !== "supplement") {
        throw new Error("只有本单元的补查执行方可预检");
      }
      const spec = unitOf(frame, args.unit);
      const bytes = readBytes(frame.root, spec.candidate);
      if (!bytes) throw new Error("候选文件尚未交付");
      return supplementChecks(frame.root, spec, lineList(bytes), frame.reads, assignment[1]);
    }
    const { parent, ...result } = report(args, exec);
    try {
      const notice = "building-loop 已落盘 " + JSON.stringify(result);
      await ctx.subagents.sendMessage(exec.agent, parent, [{ type: "text", text: notice }], { signal: exec.signal });
      return { ...result, notified: true };
    } catch {
      return { ...result, notified: false };
    }
  }

  const deny = exec => {
    if (exec.name === WORKFLOW || exec.name === FILE || exec.name === ASSESS || exec.name === LEDGER) return undefined;
    return "[building-loop/denied] 原生工具 " + exec.name + " 禁止直接调用。使用受控文件或派单入口";
  };
  ctx.tools.guard(deny);
  ctx.on("tools/pre-execute", (exec, next) => {
    const reason = deny(exec);
    return reason ? { kind: "deny", reason } : next();
  });
  ctx.on("agent/pre-step", async (_request, next) => {
    const decision = await next();
    if (decision.kind !== "enter") return decision;
    return { ...decision, messages: decision.messages.filter(message => message.source?.kind !== "agent-instructions") };
  });
  ctx.on("session/event", (session, event) => {
    if (event.type === "user/message") {
      if (event.data?.source?.kind !== "user") return;
      const agent = ctx.agents.get(session.id);
      try { if (agent?.session === session) change(agent, frame => captureRequest(frame, event)); }
      catch (error) { ctx.logger.warn("building-loop 无法登记用户消息 " + error.message); }
      return;
    }
    if (event.type !== "turn/end" || !["error", "max-tokens", "blocked"].includes(event.data?.reason?.kind)) return;
    const agent = ctx.agents.get(session.id);
    if (agent?.session !== session || session.header.parentSession === undefined) return;
    try {
      change(agent, frame => {
        if (!frame.assignment) return;
        const [id, active] = frame.assignment;
        pause(active, "子会话中断 " + event.data.reason.kind + "，本阶段未交付。总控可续派到原会话。");
        trackUnit(frame, id, active, true);
        active.interruptions = (active.interruptions ?? 0) + 1;
        frame.changed = true;
      });
    } catch (error) { ctx.logger.warn("building-loop 无法记录子会话中断 " + error.message); }
  });

  ctx.tools.register(tool(FILE, "按当前角色的准确路径白名单列出、读取、字面搜索或原子写入 UTF-8 文件。写入自动维护一份改前备份和逐文件日志。history 取授权文件的最近更新。", ["list", "read", "search", "write", "history"], {
    path: string, query: string, content: string, note: string, start: number, count: number,
  }, fileAction));

  const qualityFields = Object.fromEntries(Object.entries(QUALITY).map(([key, description]) => [key, { ...string, description }]));
  const qualityNames = Object.keys(QUALITY);
  const referenceSchema = { type: "object", properties: { file: string, start: number, end: number }, required: ["file", "start", "end"], additionalProperties: false };
  ctx.tools.register(tool(ASSESS, "独立核验方在 review 前记录六项质量依据。每项一句具体判断，revise 列出要退回的项，均通过时填 []。此工具不关单。", ["assess"], {
    unit: string, ...qualityFields,
    goalFit: { type: "object", properties: { pass: { type: "boolean" }, basis: string }, required: ["pass","basis"], additionalProperties: false },
    revisions: { type: "array", items: { type: "object", properties: {
      field: { type: "string", enum: qualityNames }, change: string, requirement: referenceSchema,
    }, required: ["field","change","requirement"], additionalProperties: false } },
    suggestions: { type: "array", items: string, maxItems: 12 },
    revise: { type: "array", items: { type: "string", enum: qualityNames } },
    sourceRefs: { type: "array", items: referenceSchema },
    unverifiedSources: { type: "array", items: string },
    unlisted: { type: "array", items: { type: "object", properties: { line: number, basis: string }, required: ["line", "basis"], additionalProperties: false } },
  }, assess, ["unit", ...qualityNames, "revise", "sourceRefs", "unverifiedSources", "unlisted", "goalFit"]));
  ctx.tools.register(tool(LEDGER, "总控登记后续计划、临时需求和搁置事项。每轮事实验收后 read 最新账本，读取项目现状，再逐项 review，保留、续做、延期或有依据地完成、覆盖、失效。", ["read", "record", "review"], {
    unit: string, id: string, kind: { type: "string", enum: ["planned", "temporary", "interrupted"] },
    title: string, note: string, originId: string, includeClosed: { type: "boolean" },
    decisions: { type: "array", items: { type: "object", properties: {
      id: string, outcome: { type: "string", enum: ["keep", "resume", "defer", "completed", "covered", "obsolete"] },
      basis: string, evidence: referenceSchema, coveredBy: string,
    }, required: ["id", "outcome", "basis"], additionalProperties: false } },
  }, (args, exec) => change(exec.agent, frame => ledgerAction(frame, args))));
  ctx.tools.register(tool(WORKFLOW, "按状态派发、续用、交付和验收。advance 仅总控。preflight 和补查 submit 由执行方使用。review 仅核验方，提交逐条事实 checks。事实支持时须先用 building_loop_quality。宿主写回执。", ["status", "advance", "preflight", "submit", "review", "block"], {
    unit: string, note: string,
    checks: { type: "array", items: {
      type: "object", properties: {
        id: string, status: { type: "string", enum: ["supported", "unsupported"] },
        line: { ...number, description: "退回项在候选中没有编号行时填写候选行号" },
        file: { ...string, description: "支持项必填。实际读取的原文项目相对路径" },
        start: { ...number, description: "支持项必填。原文起始行，1 起计" },
        end: { ...number, description: "支持项必填。原文结束行，1 起计" },
        basis: { ...string, description: "为何支持或为何不足" },
        finding: { type: "object", properties: { kind: { type: "string", enum: ["missing-evidence","contradiction","scope"] },
          quote: string, fix: string }, required: ["kind","quote","fix"], additionalProperties: false },
      }, required: ["id", "status", "basis"], additionalProperties: false,
    } },
    quality: { type: "object", properties: qualityFields, required: qualityNames, additionalProperties: false },
  }, workflow));

  ctx.systemPrompt.context({
    name: "building-loop.phase", order: 130, required: true, interpolate: false,
    text({ agent, scope: owner }) {
      try {
        const frame = scope(agent ?? owner);
        const assignment = frame.assignment;
        const units = frame.role === "coordinator" ? viewUnits(frame) : null;
        const current = units?.find(unit => unit.owned && unit.goalStale)
          ?? units?.find(unit => unit.owned && !TERMINAL.has(unit.phase) && unit.phase !== "blocked")
          ?? units?.find(unit => unit.owned && unit.phase === "blocked");
        const closed = units?.length && units.every(unit => TERMINAL.has(unit.phase));
        const phase = assignment?.[1].phase ?? (units ? current?.phase ?? (closed ? "closed" : "dispatch") : "idle");
        const rule = frame.role === "coordinator"
          ? (current?.goalStale ? COORDINATOR["goal-review-ready"] : COORDINATOR[phase] ?? "等待当前阶段交付或核验回执。") + " 总控只读写白名单内的中央文件和回执。"
          : RULES[phase] ?? "本子会话当前无工作授权，等待总控。";
        const descriptor = "building-loop role=" + frame.role + " phase=" + phase;
        if (frame.role === "idle") return descriptor + "\n" + rule;
        const shared = frame.policy.instructions.map(file => {
          const bytes = readBytes(frame.root, file, 12 * 1024);
          return bytes ? "项目规则 " + file + "\n" + text(bytes) : "";
        }).filter(Boolean);
        const goals = frame.policy.goalContext.map(file => {
          const bytes = readBytes(frame.root, file, 12 * 1024);
          return bytes ? "当前目标（高于旧派单说明） " + file + "\n" + text(bytes) : "当前目标缺失 " + file;
        });
        const detail = assignment ? {
          unit: assignment[0], candidate: unitOf(frame, assignment[0]).candidate, receipt: assignment[1].receipt,
          ...(frame.role === "reviewer" ? { claims: unitOf(frame, assignment[0]).claims } : {}),
          ...(phase === "final-review" && assignment[1].quality ? { executionQuality: assignment[1].quality } : {}),
        } : units;
        return [descriptor, rule, ...(frame.role === "reviewer" ? [REVIEW_FORMAT] : []),
          ...(phase === "supplement" || frame.role === "reviewer" ? [QUALITY_RULE] : []),
          "文件与阶段用 building_loop 和 building_loop_file。" + (frame.role === "reviewer" ? "质量判断用 building_loop_quality。" : ""),
          ...(frame.role === "coordinator" ? ["计划、临时需求和中断事项记入 building_loop_ledger。用户消息已自动登记待判定，结合现状分类处置。",
            "已有请求用 originId 关联记录，不另起同义任务。covered 必须 coveredBy 指向当前目标下验收通过的单元；read 返回覆盖关系。",
            JSON.stringify({ ledger: ledgerSummary(frame).items.map(({ id, kind, title, status }) => ({ id, kind, title, status })) })] : []),
          JSON.stringify({ read: frame.reads, write: frame.writes, detail }), ...shared, ...goals].join("\n");
      } catch (error) {
        return "building-loop role=blocked phase=authority\n" + error.message + "。请项目维护者核对 " + AUTHORITY + "。";
      }
    },
  });
}

/** 合并已读范围，让多次分页读取能构成完整读回。 */
function mergeRanges(ranges) {
  const merged = [];
  for (const [start, end] of ranges.sort((left, right) => left[0] - right[0])) {
    const last = merged.at(-1);
    if (last && start <= last[1] + 1) last[1] = Math.max(last[1], end);
    else merged.push([start, end]);
  }
  return merged;
}

/** 验收必须完整读过当前候选，禁止沿用旧版本阅读记录。 */
function reviewCandidate(frame, active, spec) {
  const bytes = readBytes(frame.root, spec.candidate);
  const seen = active.seen[keyOf(spec.candidate)];
  if (!bytes || seen?.hash !== digest(bytes) || !seen.ranges.some(([a, b]) => a === 1 && b >= lineList(bytes).length)) {
    throw new Error("验收前须完整读取当前候选正文");
  }
  return bytes;
}

/** Blocking quality requirements need a current rule locator; optional advice stays advisory. */
function validateRevisions(frame, active, revisions, fields) {
  if (!Array.isArray(revisions) || revisions.length > 12) throw new Error("revisions 须列出具体质量退回项");
  const results = revisions.map(item => {
    if (!fields.includes(item.field)) throw new Error("质量修订须对应 revise 中的字段");
    const { file, start, end } = item.requirement ?? {};
    const bytes = includes([...frame.policy.instructions, ...frame.policy.goalContext], file ?? "") && readBytes(frame.root, file);
    const seen = active.seen?.[keyOf(file ?? "")];
    if (!bytes || seen?.hash !== digest(bytes) || !Number.isSafeInteger(start) || !Number.isSafeInteger(end)
      || start < 1 || end < start || end > lineList(bytes).length || !seen.ranges.some(([a,b]) => a <= start && b >= end)) {
      throw new Error("质量退回须引用已读的当前目标或规则原文，选做建议请放 suggestions");
    }
    return { field: item.field, change: requireText(item.change,"最小质量改动"), requirement: { file,start,end,sha256:digest(bytes) } };
  });
  if (fields.some(field => !results.some(item => item.field === field))) throw new Error("每项 revise 都须有 revisions 的具体改动和要求出处");
  return results;
}

/** 覆盖项目最低断言与候选新增编号，再核每项原始出处。 */
function reviewChecks(frame, active, spec, grant, checks, candidate) {
  if (!Array.isArray(checks) || checks.length > 64) throw new Error("核验须逐条提交检查结果");
  const byId = new Map();
  const declared = expectedClaims(spec, candidate);
  for (const check of checks) {
    const id = check?.id;
    if (typeof id !== "string" || !/^[A-Za-z0-9_-]{1,48}$/.test(id) || byId.has(id)
      || declared.length && !declared.includes(id)) throw new Error("核验编号无效、重复或超范围");
    byId.set(id, check);
  }
  const ids = declared.length ? declared : [...byId.keys()];
  if (!ids.length) throw new Error("至少需要一项核验结果");
  return ids.map(id => {
    const check = byId.get(id);
    if (!check) return { id, status: "unsupported", basis: "缺少核验结果" };
    const basis = requireText(check.basis, "核验依据", 600);
    const reject = Number.isSafeInteger(check.line) ? { id, status: "unsupported", line: check.line } : { id, status: "unsupported" };
    if (check.status !== "supported") {
      const finding = check.finding;
      const row = claimRow(candidate, id) ?? (check.line ? { body: candidate[check.line-1] ?? "" } : null);
      if (!finding || !["missing-evidence","contradiction","scope"].includes(finding.kind)
        || typeof finding.quote !== "string" || !finding.quote.trim() || !row?.body.includes(finding.quote)) {
        throw new Error(id + " 的事实退回须 finding.kind、候选中真实存在的 quote 和最小 fix；表达建议不能填 unsupported");
      }
      const fix = requireText(finding.fix, "事实最小修正");
      const counterEvidence = finding.kind === "contradiction" ? evidenceReference(frame, active, spec, check) : undefined;
      return { ...reject, basis, finding: { kind:finding.kind, quote:finding.quote, fix }, ...(counterEvidence ? { counterEvidence } : {}) };
    }
    const fail = reason => ({ ...reject, basis: reason + "。" + basis });
    let file;
    try { file = relativeName(check.file); }
    catch { throw new Error(id + " 的支持项需要有效的原文路径"); }
    if (!includes(grant.evidence, file)) return fail("出处不在核验授权范围");
    const evidence = readBytes(frame.root, file);
    const coverage = active.seen[keyOf(file)];
    if (!evidence || coverage?.hash !== digest(evidence) || !Number.isSafeInteger(check.start) || !Number.isSafeInteger(check.end)
      || check.start < 1 || check.end < check.start || !coverage.ranges.some(([a, b]) => a <= check.start && b >= check.end)) {
      throw new Error(id + " 的原文行未读、行号无效或来源已变，请读取后重新核验");
    }
    let line = Number.isSafeInteger(check.line) ? check.line : null;
    if (declared.length) {
      const row = claimRow(candidate, id);
      const cited = row && citation(row.body, file);
      if (!cited) return fail("候选断言行缺少对应出处");
      if (cited.start && (check.end < cited.start || check.start > cited.end
        || !coverage.ranges.some(([a, b]) => a <= cited.start && b >= cited.end))) return fail("候选所引原文行与核验位置不一致或未完整读取");
      line = row.line;
    }
    const proof = evidenceReference(frame, active, spec, check);
    return { id, status: "supported", ...proof, line, basis };
  });
}

/** 续派前等原子会话收尾，超时保持原状态以便重试。 */
async function waitIdle(agent, signal) {
  const bounded = AbortSignal.any([signal, AbortSignal.timeout(20000)]);
  bounded.throwIfAborted();
  let abort;
  try {
    await Promise.race([agent.whenIdle(), new Promise((_, reject) => {
      abort = () => reject(bounded.reason);
      bounded.addEventListener("abort", abort, { once: true });
    })]);
  } finally { if (abort) bounded.removeEventListener("abort", abort); }
}

import { digest, includes, keyOf, readBytes } from "./policy.mjs";
import { lineList } from "./preflight.mjs";
import { acceptedVersion } from "./goals.mjs";

export const TERMINAL = new Set(["closed", "retired"]);
const FINISHED = new Set(["completed", "covered", "obsolete"]);

/** Keep the book in the same locked, atomic state file as workflow transitions. */
function book(frame) {
  frame.state.ledger ??= { revision: 0, items: {} };
  frame.state.ledger.items = Object.assign(Object.create(null), frame.state.ledger.items);
  return frame.state.ledger;
}

/** Reject empty decisions and placeholders that hide the reason for a disposition. */
function reason(value, limit = 1200) {
  if (typeof value !== "string" || !value.trim() || value.length > limit) throw new Error("账本操作需要具体原因或项目现状依据");
  return value.trim();
}

/** Add or amend a stable item without silently replacing another task's identity. */
function put(frame, id, value) {
  const ledger = book(frame);
  const previous = ledger.items[id];
  const after = { ...previous, ...value, id };
  if (JSON.stringify(previous) === JSON.stringify(after)) return after;
  ledger.items[id] = { ...after, updatedAt: new Date().toISOString() };
  ledger.revision++;
  frame.changed = true;
  return ledger.items[id];
}

/** Capture direct human messages so a mid-task request remains discoverable. */
export function captureRequest(frame, event) {
  const message = event.data;
  if (frame.role !== "coordinator" || message?.source?.kind !== "user") return;
  const text = (message.content ?? []).filter(part => part.type === "text").map(part => part.text).join("\n").trim();
  if (!text) return;
  const id = "request-" + digest(frame.agent.id + "/" + event.seq).slice(0, 20);
  if (book(frame).items[id]) return;
  const running = Object.values(frame.state.units).some(unit => !TERMINAL.has(unit.phase));
  put(frame, id, { kind: running ? "temporary" : "planned", status: "pending",
    title: text.replace(/\s+/g, " ").slice(0, 120), note: "用户消息待结合项目现状判定，原文见会话事件。",
    origin: { session: frame.agent.id, event: event.seq, sha256: digest(text) }, owner: frame.agent.id });
  // A notice consumed after closure must still receive a ledger checkpoint.
  // This reopens administration only; a changed goal still forces independent review.
  if (!running) {
    const recent = Object.entries(frame.state.units).filter(([,unit]) => unit.owner === frame.agent.id && unit.phase === "closed")
      .sort((a,b) => (b[1].closedAt ?? "").localeCompare(a[1].closedAt ?? ""))[0];
    if (recent) {
      const [unitId, active] = recent;
      const receipt = readBytes(frame.root, active.receipt);
      if (receipt) beginLedgerReview(frame, unitId, active, receipt);
    }
  }
}

/** Track dispatched and interrupted units even if the model omits a book call. */
export function trackUnit(frame, id, active, interrupted = false) {
  const prior = book(frame).items["unit-" + id];
  put(frame, "unit-" + id, { kind: interrupted ? "interrupted" : prior?.kind ?? "planned",
    status: interrupted ? "deferred" : "running", title: "工作单元 " + id,
    unit: id, owner: active.owner, note: interrupted ? active.blocked : "当前阶段 " + active.phase,
    ...(interrupted ? { lastInterruption: { reason: active.blocked, phase: active.resumePhase } } : {}) });
}

/** Expose open work; historical dispositions remain stored and available on demand. */
export function ledgerSummary(frame, includeClosed = false) {
  const ledger = book(frame);
  const items = Object.values(ledger.items).filter(item => item.owner === frame.agent.id && (includeClosed || !FINISHED.has(item.status)));
  return { revision: ledger.revision, items };
}

/** Record a fresh coordinator read of a context file during the closing checkpoint. */
export function noteContextRead(frame, file, hash, start, end) {
  if (frame.role !== "coordinator") return;
  for (const active of Object.values(frame.state.units)) {
    if (active.owner !== frame.agent.id || active.phase !== "ledger-review") continue;
    if (!includes([...frame.policy.ledgerContext, ...frame.policy.goalContext, active.receipt], file)) continue;
    active.ledgerSeen ??= {};
    const previous = active.ledgerSeen[keyOf(file)];
    const ranges = previous?.hash === hash ? previous.ranges : [];
    active.ledgerSeen[keyOf(file)] = { hash, ranges: [...ranges, [start, end]] };
    frame.changed = true;
  }
}

/** Open a mandatory book review after factual acceptance, before workflow closure. */
export function beginLedgerReview(frame, id, active, receiptBytes) {
  active.phase = "ledger-review";
  active.receiptHash = digest(receiptBytes);
  active.ledgerSeen = {};
  delete active.ledgerRead;
  trackUnit(frame, id, active);
}

/** Require a current, authorized context locator for covered or obsolete work. */
function contextReference(frame, active, value) {
  const file = value?.file;
  if (!includes([...frame.policy.ledgerContext, ...frame.policy.goalContext, active.receipt], file ?? "")) throw new Error("账本处置依据须来自本轮授权的项目现状文件或验收回执");
  const bytes = readBytes(frame.root, file);
  const seen = active.ledgerSeen?.[keyOf(file)];
  const { start, end } = value;
  if (!bytes || seen?.hash !== digest(bytes) || !Number.isSafeInteger(start) || !Number.isSafeInteger(end)
    || start < 1 || end < start || end > lineList(bytes).length
    || !seen.ranges.some(([a, b]) => a <= start && b >= end)) throw new Error("请在本轮账本复核中实际读取处置依据的当前原文行");
  return { file, start, end, sha256: digest(bytes) };
}

/** Apply explicit dispositions to every open item, guarding stale and partial reads. */
export function ledgerAction(frame, args) {
  if (frame.role !== "coordinator") throw new Error("账本由总控维护，执行方通过阻塞回执登记中断");
  const ledger = book(frame);
  if (args.action === "record") {
    const linked = args.originId && ledger.items[args.originId];
    if (args.originId && (!linked?.origin || linked.owner !== frame.agent.id)) throw new Error("originId 须指向本总控已有的自动请求记录");
    const id = linked?.id ?? args.id;
    if (!linked && (!/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(id ?? "") || id.startsWith("unit-") || id.startsWith("request-"))) throw new Error("已有请求请用 originId 关联；独立计划须使用稳定编号");
    if (!["planned", "temporary", "interrupted"].includes(args.kind)) throw new Error("账本分类须为 planned、temporary 或 interrupted");
    const title = reason(args.title, 300), note = reason(args.note);
    const previous = ledger.items[id];
    if (previous && previous.owner !== frame.agent.id) throw new Error("账目由其他总控持有");
    const duplicate = Object.values(ledger.items).find(item => item.owner === frame.agent.id && item.id !== id
      && item.title.normalize("NFKC").replace(/\s/g, "") === title.normalize("NFKC").replace(/\s/g, ""));
    if (duplicate) throw new Error("同名事项已登记 " + duplicate.id + "，请沿用原编号或 originId");
    // Reclassification never reopens completed/covered/obsolete items.
    return put(frame, id, { kind: args.kind, title, note, status: previous?.status ?? "pending", owner: frame.agent.id });
  }
  // A single owned checkpoint is unambiguous when the caller reads the global book.
  const unitId = args.unit ?? Object.keys(frame.state.units).find(id =>
    frame.state.units[id].owner === frame.agent.id && frame.state.units[id].phase === "ledger-review");
  const active = frame.state.units[unitId];
  if (args.action === "read") {
    const view = ledgerSummary(frame, args.includeClosed === true);
    if (active?.owner === frame.agent.id && active.phase === "ledger-review") {
      active.ledgerRead = { revision: ledger.revision, serial: active.serial };
      frame.changed = true;
    }
    return { ...view, context: [...new Set([...frame.policy.ledgerContext, ...frame.policy.goalContext])],
      coverage: active ? frame.policy.units[unitId].covers.map(id => ({ id,coveredBy:unitId })) : [],
      current: active ? { unit: unitId, phase: active.phase, receipt: active.receipt } : null };
  }
  const requestHash = digest(JSON.stringify({ note: args.note, decisions: args.decisions }));
  if (args.action === "review" && active?.owner === frame.agent.id && active.phase === "closed"
    && active.ledgerDecision?.requestHash === requestHash) {
    acceptedVersion(frame, unitId, active);
    return { unit: unitId, phase: "closed", replayed: true };
  }
  if (args.action !== "review" || !active || active.owner !== frame.agent.id || active.phase !== "ledger-review") throw new Error("当前没有由本总控持有的账本复核阶段");
  if (active.ledgerRead?.revision !== ledger.revision || active.ledgerRead?.serial !== active.serial) throw new Error("请先调用账本 read（unit=" + unitId + "）读取最新账本，变更后须重新读取");
  acceptedVersion(frame, unitId, active);
  for (const file of [...new Set([...frame.policy.ledgerContext, ...frame.policy.goalContext])]) {
    const bytes = readBytes(frame.root, file);
    if (!bytes || active.ledgerSeen?.[keyOf(file)]?.hash !== digest(bytes)) throw new Error("请先读取最新项目现状 " + file);
  }
  const items = ledgerSummary(frame).items;
  if (!Array.isArray(args.decisions) || args.decisions.length !== items.length
    || new Set(args.decisions.map(row => row.id)).size !== items.length) throw new Error("请逐项处置全部未结账目，保留或续做也需给原因");
  const planned = items.map(item => {
    const decision = args.decisions.find(row => row.id === item.id);
    if (!decision || !["keep", "resume", "defer", "completed", "covered", "obsolete"].includes(decision.outcome)) throw new Error("账本处置项缺失或状态无效 " + item.id);
    const basis = reason(decision.basis);
    const evidence = FINISHED.has(decision.outcome) ? contextReference(frame, active, decision.evidence) : null;
    if (frame.policy.units[unitId].covers.includes(item.id) && !["covered","obsolete"].includes(decision.outcome)) {
      throw new Error(item.id + " 已声明由本轮当前目标下的验收产物替代，请 covered 并填 coveredBy；关系确已失效时引用当前目标标 obsolete");
    }
    let coverage;
    if (decision.outcome === "covered") {
      const covering = frame.state.units[decision.coveredBy];
      if (!covering || covering.owner !== frame.agent.id || !["closed","ledger-review"].includes(covering.phase)) throw new Error("coveredBy 须指向本总控已验收单元");
      const proof = acceptedVersion(frame, decision.coveredBy, covering);
      coverage = { unit: decision.coveredBy, receipt: covering.receipt, receiptHash: covering.receiptHash,
        candidateSha256: proof.candidateSha256, goal: proof.goal };
    }
    if (item.id === "unit-" + unitId && decision.outcome !== "completed") throw new Error("本轮已验收单元须以验收回执登记完成");
    if (item.id === "unit-" + unitId && evidence?.file !== active.receipt) throw new Error("本轮完成依据须对应本轮验收回执");
    const unit = item.unit && frame.state.units[item.unit];
    if (unit && item.unit !== unitId && FINISHED.has(decision.outcome)
      && (unit.owner !== frame.agent.id || unit.phase !== "blocked")) throw new Error("其他运行中单元的权限和验收由其原总控维护");
    return { item, outcome: decision.outcome, basis, evidence, unit, coverage };
  });
  const context = reason(args.note);
  for (const { item, outcome, basis, evidence, unit, coverage } of planned) {
    put(frame, item.id, { status: outcome === "keep" ? item.status : outcome === "resume" ? "pending" : outcome === "defer" ? "deferred" : outcome,
      disposition: { outcome, basis, evidence, checkpoint: unitId, ...(coverage ? { coverage } : {}) }, note: basis });
    if (unit && item.unit !== unitId && FINISHED.has(outcome)) {
      unit.phase = "retired";
      unit.retirement = { outcome, basis, evidence };
    }
  }
  active.phase = "closed";
  active.closedAt = new Date().toISOString();
  active.ledgerDecision = { revision: ledger.revision, context, reviewed: planned.map(row => row.item.id), requestHash };
  frame.changed = true;
  return { unit: unitId, phase: "closed", ledgerRevision: ledger.revision, reviewed: planned.length };
}

import fs from "node:fs";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";

export const AUTHORITY = "BUILDING-LOOP.json";
export const MANAGED = ".building-loop";
export const PHASES = ["intake", "first-review", "supplement", "final-review"];
const LIMIT = 256 * 1024;

export const digest = bytes => createHash("sha256").update(bytes).digest("hex");
export const keyOf = value => process.platform === "win32" ? value.toLowerCase() : value;

/** 只接受普通项目相对路径，内部记录由宿主专用调用访问。 */
export function relativeName(value, internal = false) {
  if (typeof value !== "string" || !value || value.length > 500) throw new Error("需要明确的项目相对文件路径");
  const parts = value.replaceAll("\\", "/").split("/");
  if (parts.some(part => !part || part === "." || part === ".." || /[:*?"<>|\x00-\x1f]|[. ]$/.test(part)
    || /^(?:con|prn|aux|nul|com[0-9¹²³]|lpt[0-9¹²³])(?:\.|$)/i.test(part))) {
    throw new Error("拒绝绝对路径、通配符、路径别名和上级目录");
  }
  const first = parts[0].toLowerCase();
  if (!internal && [AUTHORITY.toLowerCase(), MANAGED, ".git"].includes(first)) throw new Error("授权文件和运行记录由宿主管理");
  return parts.join("/");
}

/** 文件不存在是可预期状态，其他读取错误向上保留。 */
function stat(file) {
  try { return fs.lstatSync(file); }
  catch (error) { if (error.code === "ENOENT") return null; throw error; }
}

/** 解析真实工作区并防止项目范围覆盖 DSH 私人数据目录。 */
export function workspaceRoot(value, hostHome) {
  if (typeof value !== "string" || !path.isAbsolute(value)) throw new Error("请先选择本地项目目录");
  const root = fs.realpathSync.native(value);
  if (!stat(root)?.isDirectory()) throw new Error("工作区需要是本地目录");
  const home = fs.realpathSync.native(hostHome);
  const overlap = (a, b) => {
    const relative = path.relative(a, b);
    return relative === "" || !path.isAbsolute(relative) && !relative.startsWith(".." + path.sep) && relative !== "..";
  };
  if (overlap(root, home) || overlap(home, root)) throw new Error("工作区不能与 DSH 数据目录重叠");
  return root;
}

/** 逐段拒绝链接、硬链接和别名，创建父目录也走同一规则。 */
function resolveFile(root, name, createParents = false) {
  const parts = relativeName(name, true).split("/");
  let file = root;
  for (let i = 0; i < parts.length; i++) {
    file = path.join(file, parts[i]);
    const final = i === parts.length - 1;
    let entry = stat(file);
    if (!entry && !final && createParents) {
      try { fs.mkdirSync(file); }
      catch (error) { if (error.code !== "EEXIST") throw error; }
      entry = stat(file);
    }
    if (!entry) {
      if (!final) return { file: path.join(root, ...parts), entry: null };
      return { file, entry: null };
    }
    if (entry.isSymbolicLink() || keyOf(fs.realpathSync.native(file)) !== keyOf(file)
      || (final ? !entry.isFile() || entry.nlink !== 1 : !entry.isDirectory())) {
      throw new Error("拒绝链接、硬链接、路径别名和非普通文件");
    }
  }
  return { file, entry: stat(file) };
}

/** 打开后再次核文件身份和大小，防止检查与读取之间被替换。 */
export function readBytes(root, name, limit = LIMIT) {
  const { file, entry } = resolveFile(root, name);
  if (!entry) return null;
  if (entry.size > limit) throw new Error("文件超过受控工具的大小上限");
  const fd = fs.openSync(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0));
  try {
    const opened = fs.fstatSync(fd);
    if (opened.dev !== entry.dev || opened.ino !== entry.ino || opened.nlink !== 1 || !opened.isFile() || opened.size > limit) {
      throw new Error("文件身份在读取前发生变化");
    }
    const bytes = Buffer.alloc(limit + 1);
    let size = 0;
    while (size < bytes.length) {
      const count = fs.readSync(fd, bytes, size, bytes.length - size, null);
      if (!count) break;
      size += count;
    }
    if (size > limit) throw new Error("文件超过受控工具的大小上限");
    return bytes.subarray(0, size);
  } finally {
    fs.closeSync(fd);
  }
}

/** 严格解码 UTF-8，损坏字节需要修复后才能作为证据。 */
export function text(bytes) {
  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
}

/** 比较文件当前版本，同时区分不存在和空文件。 */
export function equal(left, right) {
  return left === null ? right === null : right !== null && left.equals(right);
}

/** 同卷暂存、刷新、核改前版本后替换，失败清理暂存。 */
export function replaceBytes(root, name, bytes, before) {
  const { file } = resolveFile(root, name, bytes !== null);
  if (bytes === null) {
    if (!equal(readBytes(root, name), before)) throw new Error("文件在写入前发生变化");
    if (before !== null) fs.unlinkSync(file);
    return;
  }
  if (bytes.length > LIMIT) throw new Error("内容超过受控工具的大小上限");
  const temp = path.join(path.dirname(file), ".building-loop-write-" + randomUUID());
  let staged = false;
  try {
    const fd = fs.openSync(temp, "wx", 0o600);
    staged = true;
    try {
      fs.writeFileSync(fd, bytes);
      fs.fsyncSync(fd);
    } finally { fs.closeSync(fd); }
    if (!equal(readBytes(root, name), before)) throw new Error("文件在写入前发生变化");
    fs.renameSync(temp, file);
    staged = false;
  } finally { if (staged) fs.unlinkSync(temp); }
}

/** 规范授权路径数组并拒绝重复登记。 */
function pathList(value = []) {
  if (!Array.isArray(value) || value.length > 80) throw new Error("授权文件须为路径数组");
  const paths = value.map(item => relativeName(item));
  if (new Set(paths.map(keyOf)).size !== paths.length) throw new Error("授权文件路径重复");
  return paths;
}

/** 清单结构只接受已定义字段，拼写错误须显式修正。 */
function object(value, label, fields) {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(label + "须为对象");
  if (fields && Object.keys(value).some(name => !fields.includes(name))) throw new Error(label + "包含未知字段");
  return value;
}

/** 把各角色读写权限解析成统一形式。 */
function grants(value, label, fields = []) {
  object(value, label, ["read", "write", ...fields]);
  return { read: pathList(value.read), write: pathList(value.write) };
}

/** 路径匹配遵循当前平台大小写规则，避免 Windows 别名绕过。 */
export function includes(paths, name) {
  return paths.some(item => keyOf(item) === keyOf(name));
}

/** 解析项目权威清单，核角色隔离、证据只读和来源凭据。 */
export function authority(root) {
  const bytes = readBytes(root, AUTHORITY, 64 * 1024);
  if (!bytes) throw new Error("需要项目维护者配置 " + AUTHORITY);
  const source = object(JSON.parse(text(bytes)), "授权文件", ["spec", "instructions", "coordinator", "units", "sourcePins", "ledgerContext", "goalContext"]);
  if (source.spec !== "building-loop/1") throw new Error("不支持的授权文件版本");
  const coordinator = grants(source.coordinator, "总控");
  const ledgerContext = pathList(source.ledgerContext);
  if (ledgerContext.length > 3 || ledgerContext.some(file => !includes(coordinator.read, file))) throw new Error("账本现状依据须在总控读授权内，最多三份");
  const goalContext = pathList(source.goalContext ?? source.ledgerContext);
  if (goalContext.length > 3 || goalContext.some(file => !includes(coordinator.read, file))) throw new Error("项目目标须为总控可读的中央文件，最多三份");
  const instructions = pathList(source.instructions);
  if (instructions.length > 3 || instructions.some(file => !includes(coordinator.read, file) || includes(coordinator.write, file))) {
    throw new Error("注入的项目规则须在总控只读授权中，最多三份");
  }
  const units = Object.create(null);
  const mutable = [...coordinator.write];
  const receiptsSeen = new Set();
  for (const [id, value] of Object.entries(object(source.units, "工作单元"))) {
    if (!/^[A-Za-z][A-Za-z0-9_-]{0,47}$/.test(id) || Object.keys(units).length >= 80) throw new Error("工作单元编号或数量无效");
    object(value, "工作单元", ["candidate", "claims", "continuation", "phases", "calculations", "requireSourcePins", "covers"]);
    if (value.requireSourcePins !== undefined && typeof value.requireSourcePins !== "boolean") throw new Error("requireSourcePins 须为布尔值");
    const candidate = relativeName(value.candidate);
    const covers = value.covers ?? [];
    if (!Array.isArray(covers) || covers.length > 80 || covers.some(id => typeof id !== "string" || !/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(id))
      || new Set(covers).size !== covers.length) throw new Error("covers 须列出唯一的被替代账目编号");
    const claims = value.claims ?? [];
    if (!Array.isArray(claims) || claims.length > 64 || claims.some(claim => typeof claim !== "string" || !/^[A-Za-z0-9_-]{1,48}$/.test(claim))
      || new Set(claims).size !== claims.length) throw new Error("断言编号无效或重复");
    const continuation = value.continuation ?? "reuse";
    if (!["reuse", "fresh"].includes(continuation)) throw new Error("未知续派方式");
    const phases = Object.create(null);
    object(value.phases, "阶段", PHASES);
    for (const phase of PHASES) {
      const review = phase.endsWith("review");
      const raw = value.phases[phase];
      const access = grants(raw, phase, review ? ["receipt", "evidence"] : []);
      if (!includes(access.read, candidate)) throw new Error("当前阶段需要候选文件读权");
      if (review) {
        if (access.write.length) throw new Error("核验方只读，回执由机制写入");
        const receipt = relativeName(raw.receipt);
        if (receiptsSeen.has(keyOf(receipt))) throw new Error("核验回执路径重复");
        receiptsSeen.add(keyOf(receipt));
        const evidence = pathList(raw.evidence);
        if (includes([...access.read, ...instructions], receipt)
          || evidence.some(file => !includes(access.read, file) || keyOf(file) === keyOf(candidate))) {
          throw new Error("核验回执与候选、证据和规则文件必须分开");
        }
        phases[phase] = { ...access, receipt, evidence };
      } else {
        phases[phase] = access;
      }
    }
    if (includes(coordinator.write, candidate) || PHASES.some(phase => phases[phase].write.some(file => includes(coordinator.write, file)))) {
      throw new Error("总控和执行方的写入授权须分开");
    }
    mutable.push(...PHASES.flatMap(phase => phases[phase].write));
    const calculations = Object.create(null);
    for (const [claim, formula] of Object.entries(object(value.calculations ?? {}, "复算规则"))) {
      if (!claims.includes(claim)) throw new Error("复算规则须绑定已登记的断言编号");
      object(formula, "复算规则", ["kind", "source", "keyColumn", "valueColumn", "before", "after", "decimals", "line", "sourceUnit", "units"]);
      const { kind, keyColumn, valueColumn, before, after, decimals = 2 } = formula;
      const source = relativeName(formula.source);
      if (kind === "source-number") {
        if (!Number.isSafeInteger(formula.line) || formula.line < 1 || typeof formula.sourceUnit !== "string" || !formula.sourceUnit.trim()
          || !Array.isArray(formula.units) || !formula.units.length || formula.units.length > 8
          || formula.units.some(unit => typeof unit !== "string" || !unit.trim() || unit.length > 40)
          || !includes(phases.supplement.read,source) || ["first-review","final-review"].some(phase=>!includes(phases[phase].evidence,source))) {
          throw new Error("原文数值核对须配置原文行、原文单位和等价交付单位，并授权各核验阶段读取");
        }
        calculations[claim] = { kind, source, line:formula.line, sourceUnit:formula.sourceUnit, units:formula.units };
        continue;
      }
      if (kind !== "percent-decrease" || !Number.isSafeInteger(decimals) || decimals < 0 || decimals > 6
        || [keyColumn, valueColumn, before, after].some(item => typeof item !== "string" || !item.trim() || item.length > 80)
        || keyColumn === valueColumn || before === after) throw new Error("无效的 CSV 降幅复算规则");
      if (!includes(phases.supplement.read, source) || !includes(phases["final-review"].evidence, source)) {
        throw new Error("复算原始文件须在补查读授权和终审证据授权内");
      }
      calculations[claim] = { kind, source, keyColumn, valueColumn, before, after, decimals };
    }
    units[id] = { candidate, claims, continuation, phases, calculations, covers, requireSourcePins: value.requireSourcePins === true };
  }
  const sourcePins = Object.create(null);
  for (const [path, entry] of Object.entries(object(source.sourcePins ?? {}, "来源凭据"))) {
    const file = relativeName(path);
    object(entry, "来源凭据", ["sha256", "kind", "locator"]);
    if (!/^[a-f0-9]{64}$/.test(entry.sha256 ?? "") || !["primary", "secondary", "synthetic"].includes(entry.kind)
      || typeof entry.locator !== "string" || !entry.locator.trim() || entry.locator.length > 1000) throw new Error("来源凭据需要原始摘要、类型和可追查位置");
    if (sourcePins[keyOf(file)]) throw new Error("来源凭据路径重复");
    sourcePins[keyOf(file)] = { sha256: entry.sha256, kind: entry.kind, locator: entry.locator.trim() };
  }
  for (const unit of Object.values(units)) {
    if (unit.requireSourcePins && ["first-review", "final-review"].some(phase =>
      unit.phases[phase].evidence.some(file => !sourcePins[keyOf(file)]))) throw new Error("本单元要求每份原始证据登记来源凭据");
  }
  const protectedFiles = [...instructions, ...Object.values(units).flatMap(unit => [
    unit.phases["first-review"].receipt, unit.phases["final-review"].receipt,
    ...unit.phases["first-review"].evidence, ...unit.phases["final-review"].evidence,
  ])];
  if (mutable.some(file => includes(protectedFiles, file))) throw new Error("指令、原始证据和核验回执不能授予模型写权");
  if (Object.values(units).some(unit => includes(goalContext, unit.candidate)
    || Object.values(unit.phases).some(phase => phase.write.some(file => includes(goalContext,file))
      || phase.receipt && includes(goalContext,phase.receipt) || phase.evidence?.some(file => includes(goalContext,file))))) {
    throw new Error("目标文件须与候选、模块写入、证据和回执分开");
  }
  return { hash: digest(bytes), coordinator, instructions, units, sourcePins, ledgerContext, goalContext };
}

/** 受控写入事务维护正文、单份改前备份和逐文件更新记录。 */
export function replaceWithHistory(root, file, content, note, tag, markers) {
  const before = readBytes(root, file);
  const after = Buffer.from(content, "utf8");
  if (equal(before, after)) return { path: file, changed: false, sha256: digest(after) };
  const log = MANAGED + "/changes/" + file + ".md";
  const backup = MANAGED + "/latest_backup/" + file;
  const oldLog = readBytes(root, log);
  const summary = note.trim().replace(/\s+/g, " ").slice(0, 500);
  const record = "- " + new Date().toISOString() + " " + tag + " " + summary + " SHA-256 " + digest(after) + "\n";
  const history = Buffer.from(record + (oldLog ? text(oldLog) : ""), "utf8");
  if (history.length > LIMIT || after.length > LIMIT) throw new Error("内容或更新日志超过受控工具的大小上限");
  const marker = keyOf(file);
  if (markers[marker] !== tag) {
    if (before) replaceBytes(root, backup, before, readBytes(root, backup));
    if (oldLog) {
      const logBackup = MANAGED + "/latest_backup/" + log;
      replaceBytes(root, logBackup, oldLog, readBytes(root, logBackup));
    }
  }
  replaceBytes(root, log, history, oldLog);
  try { replaceBytes(root, file, after, before); }
  catch (error) {
    replaceBytes(root, log, oldLog, history);
    throw error;
  }
  markers[marker] = tag;
  return { path: file, changed: true, sha256: digest(after), log, ...(before ? { backup } : {}) };
}

import { digest, includes, keyOf, readBytes, text } from "./policy.mjs";

export const QUALITY = {
  sources: "资料的原始出处、核实办法和仍待证的部分",
  conclusion: "可支持的结论、修订理由与适用范围",
  method: "采用的方法、复算或反查及其局限",
  alternatives: "可行的备选、取舍和更合适的提议",
  detail: "先摘要后依据的层次、读者需要的细节",
  plain: "面向读者的一句大白话",
};

export const lineList = bytes => text(bytes).split(/\r\n|\n|\r/);
const escape = value => value.replace(/[|\\{}()[\]^$+*?.-]/g, "\\$&");

/** 以唯一编号定位事实行，重复编号交回修改。 */
export function claimRow(lines, id) {
  const pattern = new RegExp("^\\s*(?:[-*]\\s+|\\d+[.)]\\s+)?(?:\\*\\*)?" + escape(id) + "(?:\\*\\*)?\\s*[:：]\\s*(.*)$");
  const found = [];
  for (let i = 0; i < lines.length; i++) {
    const match = pattern.exec(lines[i]);
    if (match) found.push({ line: i + 1, body: match[1] });
  }
  return found.length === 1 ? found[0] : null;
}

/** 识别准确路径及原文行范围，排除同名前缀和备份别名。 */
export function citation(body, file) {
  const pattern = new RegExp("(^|[\\s:：\\x60\"'“‘(（\\[【〔<《,，、])" + escape(file)
    + "(?=$|[\\s#:,：，、。；;\\x60\"'”’）)\\]】〕>》]|\\.(?:\\s|$))", process.platform === "win32" ? "i" : "");
  const row = body.replaceAll("\\", "/");
  const match = pattern.exec(row);
  if (!match) return null;
  const after = row.slice(match.index + match[0].length);
  const range = /^\s*(?:\x60\s*)?(?:#L(\d+)(?:-L?(\d+))?|[:：](\d+)(?:[-–—](\d+))?|第\s*(\d+)(?:\s*[-–—、至到]\s*(\d+))?\s*行)/i.exec(after);
  if (!range) return { start: null, end: null };
  const start = Number(range[1] ?? range[3] ?? range[5]);
  const end = Number(range[2] ?? range[4] ?? range[6] ?? start);
  return Number.isSafeInteger(start) && Number.isSafeInteger(end) && start > 0 && end >= start ? { start, end } : null;
}

/** Remove only recognized locators. Facts after a citation remain in the comparison. */
function conclusion(body, files = []) {
  let result = body.normalize("NFKC").replaceAll("−", "-").replaceAll("\\", "/");
  for (const file of files) {
    const locator = new RegExp(escape(file.normalize("NFKC"))
      + "\\s*(?:#L\\d+(?:-L?\\d+)?|[:：]\\d+(?:[-–—]\\d+)?|第\\s*\\d+(?:\\s*[-–—、至到]\\s*\\d+)?\\s*行)", "gi");
    result = result.replace(locator, "");
  }
  return result.replace(/(?:出处|来源|证据|source|evidence)\s*[:：]/gi, "");
}

/** 消除排版差异，标题或标点调整不能伪装成实质补查。 */
function normalized(body) {
  return body.normalize("NFKC").replace(/[\s,，。;；!?“”‘’\x60*_()\[\]【】〔〕]+/g, "").toLowerCase();
}

/** 对结论与已读证据位置建立可比对的退回基线。 */
function shape(root, spec, row, readable, seen) {
  const refs = [];
  for (const file of spec.phases["final-review"].evidence) {
    const locate = citation(row.body, file);
    if (!locate?.start || !includes(readable, file)) continue;
    const bytes = readBytes(root, file);
    if (!bytes || locate.end > lineList(bytes).length) continue;
    const hash = digest(bytes);
    const observed = seen?.[keyOf(file)];
    if (seen && (observed?.hash !== hash || !observed.ranges.some(([a, b]) => a <= locate.start && b >= locate.end))) continue;
    refs.push({ hash, start: locate.start, end: locate.end });
  }
  return { version: 2, body: row.body, conclusion: digest(normalized(conclusion(row.body, spec.phases["final-review"].evidence))), refs };
}

/** 保存本轮被退回的实际断言，供下一轮逐项检查。 */
export function rejectedClaims(root, spec, lines, rejected, readable) {
  return Object.fromEntries(rejected.map(check => {
    const row = claimRow(lines, check.id) ?? (Number.isSafeInteger(check.line) && check.line > 0 && check.line <= lines.length
      ? { body: lines[check.line - 1] } : null);
    if (!row) throw new Error(check.id + " 的退回项缺少可定位的候选行，请提供编号行或候选行号");
    return [check.id, shape(root, spec, row, readable)];
  }));
}

/** 把普通十进制拆成整数比，复算不依赖浮点近似。 */
function decimal(value) {
  const parsed = /^([+-]?)(\d{1,18})(?:\.(\d{1,9}))?$/.exec(value);
  if (!parsed) throw new Error("原始数值需要普通十进制数字");
  const fraction = parsed[3] ?? "";
  return { n: BigInt(parsed[2] + fraction) * (parsed[1] === "-" ? -1n : 1n), scale: 10n ** BigInt(fraction.length) };
}

/** 按数值比较百分比，允许等价的小数表示。 */
function equalNumber(left, right) {
  const a = decimal(left);
  const b = decimal(right);
  return a.n * b.scale === b.n * a.scale;
}

/** 输出按声明精度取整后的十进制结果。 */
function formatDecimal(n, places) {
  const prefix = n < 0n ? "-" : "";
  const digits = (n < 0n ? -n : n).toString().padStart(places + 1, "0");
  if (!places) return prefix + digits;
  return (prefix + digits.slice(0, -places) + "." + digits.slice(-places)).replace(/0+$/, "").replace(/\.$/, "");
}

/** 从指定 CSV 行取原始值，检查口径后复算相对降幅。 */
function calculate(bytes, rule) {
  const lines = lineList(bytes);
  if (lines.some(line => line.includes('"'))) throw new Error("复算支持无引号和无跨行字段的 UTF-8 CSV");
  const header = lines[0].split(",").map(x => x.trim());
  const key = header.indexOf(rule.keyColumn);
  const value = header.indexOf(rule.valueColumn);
  if (key < 0 || value < 0 || new Set(header).size !== header.length) throw new Error("复算 CSV 表头不匹配或有重复列");
  const rows = new Map();
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = lines[i].split(",").map(x => x.trim());
    if (cells.length !== header.length) throw new Error("复算 CSV 行列数量不一致");
    if (cells[key] !== rule.before && cells[key] !== rule.after) continue;
    if (rows.has(cells[key])) throw new Error("复算 CSV 匹配到重复数据行");
    rows.set(cells[key], { raw: cells[value], line: i + 1 });
  }
  const before = rows.get(rule.before);
  const after = rows.get(rule.after);
  if (!before || !after) throw new Error("缺少配置的基准行或对照行");
  const a = decimal(before.raw);
  const b = decimal(after.raw);
  if (a.n <= 0n || b.n < 0n) throw new Error("降幅复算需要正基准和非负对照值");
  const numerator = (a.n * b.scale - b.n * a.scale) * 100n * 10n ** BigInt(rule.decimals);
  const denominator = a.n * b.scale;
  const absolute = numerator < 0n ? -numerator : numerator;
  const rounded = ((2n * absolute + denominator) / (2n * denominator)) * (numerator < 0n ? -1n : 1n);
  return { expected: formatDecimal(rounded, rule.decimals), before, after };
}

/** 每次从当前原始文件计算，核结果、来源版本和引用行。 */
export function numericChecks(root, spec, lines, readable) {
  return Object.entries(spec.calculations).map(([id, rule]) => {
    try {
      if (!includes(readable, rule.source)) throw new Error("本阶段没有原始数据的读取授权");
      const bytes = readBytes(root, rule.source);
      if (!bytes) throw new Error("复算原始文件尚未提供");
      if (rule.kind === "source-number") return sourceNumber(bytes, rule, lines, id);
      const { expected, before, after } = calculate(bytes, rule);
      const row = claimRow(lines, id);
      const cites = row && citation(row.body, rule.source);
      const body = row ? conclusion(row.body, [rule.source]) : "";
      // A literal ×100% is a formula multiplier, while 24% in a claim is a result.
      const percentages = [...body.matchAll(/(?<![\dA-Za-z.,+\-])([+-]?\d+(?:\.\d+)?)\s*%/g)]
        .filter(match => !(match[1] === "100" && /[×*]\s*$/.test(body.slice(0, match.index))))
        .map(match => match[1]);
      const correct = percentages.length > 0 && percentages.every(value => equalNumber(value, expected));
      const coversRows = cites?.start && cites.start <= Math.min(before.line, after.line)
        && cites.end >= Math.max(before.line, after.line) && cites.end <= lineList(bytes).length;
      const issue = !correct ? "结论中的降幅应为 " + expected + "%"
        : !coversRows ? "出处须引用 " + rule.source + " 中两条原始数据行" : null;
      return {
        id, ok: issue === null, issue, expected: expected + "%", reported: percentages.map(value => value + "%"),
        source: rule.source, sourceHash: digest(bytes), before, after, formula: "(基准-对照)/基准×100",
      };
    } catch (error) { return { id, ok: false, source: rule.source, issue: error.message }; }
  });
}

/** Check direct numerical restatements; conversions require a different declared formula. */
function sourceNumber(bytes, rule, lines, id) {
  const source = lineList(bytes)[rule.line-1] ?? "";
  const pattern = new RegExp("([+-]?\\d+(?:\\.\\d+)?)\\s*" + escape(rule.sourceUnit),"gi");
  const matches = [...source.matchAll(pattern)];
  if (matches.length !== 1) throw new Error("原文指定行须含唯一的数值与单位");
  const expected = matches[0][1];
  const row = claimRow(lines,id);
  const body = row ? conclusion(row.body,[rule.source]) : "";
  const values = [...body.matchAll(/(?<![\dA-Za-z.])([+-]?\d+(?:\.\d+)?)/g)].map(m=>m[1]);
  const unitPattern = new RegExp("[+-]?\\d+(?:\\.\\d+)?\\s*(?:个\\s*)?(?:"+rule.units.map(escape).join("|")+")");
  const cited = row && citation(row.body,rule.source);
  const ok = values.length > 0 && values.every(value=>equalNumber(value,expected)) && unitPattern.test(body)
    && cited?.start <= rule.line && cited?.end >= rule.line;
  return { id,ok,expected:expected+" "+rule.units[0],source:rule.source,sourceHash:digest(bytes),line:rule.line,
    reported:values,issue:ok?null:"本条直接转述须为原文的 "+expected+" "+rule.units[0]+"，引用原文第 "+rule.line+" 行；转换或旧错数不要混在当前事实行" };
}

/** 补查提交前逐项检查退回、遗漏事实及可复算数字。 */
export function supplementChecks(root, spec, lines, readable, active) {
  const issues = [];
  for (const finding of active.unlisted ?? []) {
    if (lines.some(line => normalized(line) === normalized(finding.text))) issues.push("候选第 " + finding.line + " 行的未登记事实仍未修订或编号溯源");
  }
  for (const id of active.unsupported ?? []) {
    const before = active.rejected?.[id];
    const row = claimRow(lines, id);
    if (!before) {
      issues.push(id + " 缺少退回基线，先记录阻塞并由总控重新发起补查");
      continue;
    }
    if (!row) {
      issues.push(id + " 需要保留唯一的编号断言行");
      continue;
    }
    const now = shape(root, spec, row, readable, active.seen);
    if (before.version !== 2) {
      issues.push(id + " 的旧版退回基线不含完整断言，需重新独立核验，不能沿用截断摘要");
      continue;
    }
    if (before.conclusion === now.conclusion && !now.refs.some(ref => !before.refs.some(old =>
      ref.hash === old.hash && old.start <= ref.start && old.end >= ref.end))) {
      issues.push(id + " 的退回结论与可定位证据均未变");
    }
  }
  const calculations = numericChecks(root, spec, lines, readable);
  for (const result of calculations) if (!result.ok) issues.push(result.id + " " + result.issue);
  return { ok: issues.length === 0, issues, calculations };
}

/** 质量说明须有具体内容或边界，拒绝空白和通用占位词。 */
function qualityText(value, field) {
  if (typeof value !== "string" || !value.trim() || /^(?:已核对|已检查|已优化|完成|通过|无|同上|ok|pass|n\/a)[。.!！]?$/i.test(value.trim())) {
    throw new Error("请给出质量项 " + field + " 的具体内容或适用边界");
  }
  if (value.length > 4000) throw new Error("质量项 " + field + " 超过 4000 字，请保留关键判断和证据路径");
  return value.trim();
}

/** 六项交付说明逐项保留，退回的质量项必须修订。 */
export function deliveryQuality(value, previous, rejected = []) {
  return Object.fromEntries(Object.keys(QUALITY).map(field => {
    const note = qualityText(value?.[field], field);
    if (rejected.includes(field) && normalized(note) === normalized(previous?.[field] ?? "")) {
      throw new Error("退回的质量项 " + field + " 没有修订");
    }
    return [field, note];
  }));
}

/** 独立核验的六项结果由明确退回项计算，保留具体依据。 */
export function reviewedQuality(value, revise) {
  if (!Array.isArray(revise) || revise.some(field => !Object.hasOwn(QUALITY, field))) {
    throw new Error("revise 只能列出需要退回的质量项名称");
  }
  return Object.fromEntries(Object.keys(QUALITY).map(field => [field, {
    pass: !revise.includes(field), basis: qualityText(value[field], field),
  }]));
}

import fs from "node:fs";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";

export const name = "building-loop-real-audit-witness";
export const inject = ["agentPresets", "agents", "sessions", "sessionController", "tools", "llm", "systemPrompt"];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const home = process.env.BUILDING_LOOP_REAL_RUN;
const presetId = process.env.BUILDING_LOOP_GOV_PRESET ?? "building-loop";
const route = { provider: "deepseek-official", model: "deepseek-flash", reasoningEffort: "off" };
const tracked = new Set([
  "turn/start", "turn/end", "step/start", "step/end", "user/message",
  "assistant/message", "assistant/attempt", "tool/call", "tool/result",
  "subagent/catalog", "subagent/descriptor", "agent/inbox/claimed",
  "agent/inbox/inserted", "session/model",
]);
const allowed = new Set(["read", "write", "edit", "skill", "subagent", "send_message",
  "list_agents", "wait_agent", "list_subagent_models", "todo_write", "glob", "grep", "pwsh", "building_loop", "building_loop_file", "building_loop_quality", "building_loop_ledger"]);


function json(data) {
  const key = process.env.DEEPSEEK_API_KEY;
  const text = JSON.stringify(data, (_key, value) => typeof value === "bigint" ? value.toString() : value);
  return key ? text.replaceAll(key, "[redacted]") : text;
}

function append(name, data) {
  fs.appendFileSync(path.join(home, name), json({ time: Date.now(), ...data }) + "\n", "utf8");
}

function finished(data) {
  fs.writeFileSync(path.join(home, "finished.json"), json(data) + "\n", "utf8");
}

function inside(root, target) {
  const relative = path.relative(root, target);
  return relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative);
}

export function apply(ctx) {
  const groups = new Map();
  const identities = new Map();
  let active = null;
  let initiated = false;
  const progress = data => append("progress.jsonl", data);
  const scopeOf = sessionId => identities.get(sessionId) ?? active;

  ctx.on("llm/stream", (options, next) => {
    const sid = options.sessionId;
    const group = groups.get(scopeOf(sid));
    if (sid && group) {
      const payload = JSON.stringify(options.messages);
      const marker = [...payload.matchAll(/building-loop role=([a-z-]+) phase=([a-z-]+)/g)].at(-1);
      append("events.jsonl", { group: group.name, sid, type: "fixture/request", data: {
        role: marker?.[1], phase: marker?.[2],
        unapprovedInstruction: payload.includes("TEST_ONLY_UNAUTHORIZED_INSTRUCTION_96CD8A"),
      } });
    }
    return next();
  });

  ctx.on("session/event", (session, event) => {
    if (!tracked.has(event.type)) return;
    const label = scopeOf(session.id);
    const group = groups.get(label);
    if (!group) return;
    identities.set(session.id, label);
    group.ids.add(session.id);
    group.lastEvent = Date.now();
    const data = event.type === "assistant/message"
      ? { turn: event.data.turn, step: event.data.step, usage: event.data.usage,
          source: { provider: event.data.message?.source?.provider, model: event.data.message?.source?.model },
          content: event.data.message?.content?.filter(block => block.type !== "thinking") }
      : event.type === "assistant/attempt"
        ? { turn: event.data.turn, step: event.data.step, stream: event.data.stream }
        : event.data;
    append("events.jsonl", { group: label, sid: session.id, seq: event.seq, type: event.type, data });
    if (event.type === "tool/result" && !group.goalChanged) {
      const receipt = path.join(group.workspace, "records", "audit-first.json");
      if (fs.existsSync(receipt)) {
        const first = JSON.parse(fs.readFileSync(receipt, "utf8"));
        const goal = path.join(group.workspace, "PROJECT.md");
        const before = fs.readFileSync(goal);
        const after = fs.readFileSync(path.join(home, "goal-after.md"));
        const backup = path.join(group.workspace, ".building-loop", "latest_backup", "PROJECT.md");
        const log = path.join(group.workspace, ".building-loop", "changes", "PROJECT.md.md");
        fs.mkdirSync(path.dirname(backup), { recursive: true });
        fs.mkdirSync(path.dirname(log), { recursive: true });
        fs.writeFileSync(backup, before);
        fs.writeFileSync(goal, after);
        const digest = value => createHash("sha256").update(value).digest("hex");
        const observation = { firstDecision: first.decision, beforeSha256: digest(before), afterSha256: digest(after),
          authority: "user-authorized test driver acting as project maintainer" };
        fs.writeFileSync(log, "- " + new Date().toISOString() + " 项目维护者将 G1 改为 G2，保持材料与权限清单。SHA-256 " + digest(after) + "\n");
        group.goalChanged = true;
        append("events.jsonl", { group: label, sid: session.id, type: "fixture/goal-changed", data: observation });
        progress({ group: label, event: "goal-changed-after-first-review", ...observation });
        // Use the same validated controller entry as a normal user update. The
        // driver is explicitly authorized to simulate this goal change in the fixture.
        group.goalNotice = ctx.sessionController.prompt({
          sessionId: group.root, requestId: randomUUID(), clientTimeZone: "Asia/Shanghai",
          content: [{ type: "text", text: "[受用户授权的实验目标更新] 项目维护者已更新 PROJECT.md。请重新读取当前目标，按最新总纲调整续派要求，并在本轮账本复盘时核对原计划是否仍有必要。" }],
        }, AbortSignal.timeout(10000)).then(() => {
          progress({ group: label, event: "goal-update-notification-delivered", entry: "sessionController.prompt" });
        }).catch(error => {
          group.notificationError = String(error);
          progress({ group: label, event: "goal-update-notification-error", error: String(error) });
        });
      }
    }
    if (event.type === "step/start") group.steps++;
    if (event.type === "subagent/catalog") {
      identities.set(event.data.childId, label);
      group.ids.add(event.data.childId);
      progress({ group: label, event: "child", sid: event.data.childId, label: event.data.label });
    }
    if (event.type === "turn/end") {
      const reason = event.data?.reason?.kind ?? "unknown";
      if (reason === "error" || reason === "blocked" || reason === "max-tokens") {
        progress({ group: label, event: "turn-end", sid: session.id, reason, detail: event.data?.reason?.code });
      }
    }
  });

  async function allIdle(group) {
    const agents = [...group.ids].map(id => ctx.agents.get(id)).filter(Boolean);
    return Promise.race([Promise.all(agents.map(agent => agent.whenIdle())).then(() => true), sleep(550).then(() => false)]);
  }

  // Register the original plan before the midpoint goal change occurs.
  async function seedLedger(agent) {
    for (const [id, kind, title, note] of [
      ["moon-animation", "planned", "制作月球同步自转动画", "依据当前教学网页目标，计划在事实核验后制作动画。"],
      ["extra-faq", "temporary", "另写中文 FAQ 说明", "为教学网页准备一段月球是否自转的中文简明说明。"],
      ["paused-quiz", "interrupted", "课堂测验互动", "先前暂停的互动测验，等待内容核验完成再决定恢复。"],
      ["future-link-check", "planned", "后续来源链接复核", "后续定期核对最终文档的出处链接是否仍有效。"],
    ]) {
      const result = await ctx.tools.execute({ agent,
        calls: [{ type: "tool-call", id: randomUUID(), name: "building_loop_ledger", arguments: JSON.stringify({ action: "record", id, kind, title, note }) }],
        signal: AbortSignal.timeout(8000), maxParallelToolCalls: 1 });
      if (result.results[0]?.result?.isError) throw new Error("Failed to register the original task ledger");
    }
  }

  async function runGroup(name, onlyProbe = false) {
    const directory = path.join(home, name);
    const group = { name, workspace: path.join(directory, "workspace"), ids: new Set(), steps: 0, lastEvent: Date.now() };
    groups.set(name, group);
    active = name;
    const started = Date.now();
    const { sessionId } = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: presetId });
    group.root = sessionId;
    group.ids.add(sessionId);
    identities.set(sessionId, name);
    const agent = ctx.agents.get(sessionId);
    const prompt = await ctx.systemPrompt.assemble({ agent, scope: agent });
    const context = prompt.contexts.find(entry => entry.name === "building-loop.phase");
    if (!context?.text.includes("role=coordinator phase=dispatch")) throw new Error("Governed preset has no dispatch phase");
    if (!onlyProbe) await seedLedger(agent);
    if (onlyProbe) {
      const standard = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: "standard" });
      const other = ctx.agents.get(standard.sessionId);
      const reason = ctx.tools.checkGuards({ agent: other, name: "read", arguments: { file_path: "PROJECT.md" } });
      if (String(reason).includes("building-loop/denied")) throw new Error("Guard leaked into the standard preset");
      return { group: name, status: "probed", standardUnaffected: true };
    }
    await ctx.sessionController.selectModel({ sessionId, ...route });
    const declared = ctx.tools.schemas(agent).map(definition => definition.name);
    progress({ group: name, event: "start", sid: sessionId, tools: declared.filter(tool => allowed.has(tool)) });
    const requestId = randomUUID();
    await ctx.sessionController.prompt({
      sessionId, requestId, clientTimeZone: "Asia/Shanghai",
      content: [{ type: "text", text: fs.readFileSync(path.join(directory, "prompt.txt"), "utf8") }],
    }, AbortSignal.timeout(10000));
    let end = "deadline";
    while (Date.now() - started < 480000) {
      if (group.steps > 150) {
        end = "step-budget";
        break;
      }
      if (await allIdle(group)) {
        const finalPath = path.join(group.workspace, "records", "audit-final.json");
        const hasFinal = [finalPath, path.join(group.workspace, "records", "audit-first.json")]
          .some(file => fs.existsSync(file) && JSON.parse(fs.readFileSync(file, "utf8")).decision === "accept");
        const hasLedger = fs.existsSync(path.join(group.workspace, "ledger.md"));
        const stateFiles = fs.readdirSync(path.join(process.env.DSH_HOME, "building-loop-state")).filter(name => name.endsWith(".json"));
        const closed = stateFiles.map(name => JSON.parse(fs.readFileSync(path.join(process.env.DSH_HOME, "building-loop-state", name), "utf8")))
          .some(data => data.units?.K01?.owner === sessionId && data.units.K01.phase === "closed");
        if (hasFinal && hasLedger && closed && Date.now() - group.lastEvent > 1800) {
          end = "artifacts-present";
          break;
        }
        if (Date.now() - group.lastEvent > 14000) {
          end = "idle-without-all-artifacts";
          break;
        }
      }
      await sleep(600);
    }
    const result = { group: name, event: "finish", sid: sessionId, end, wallMs: Date.now() - started,
      steps: group.steps, members: [...group.ids] };
    progress(result);
    fs.writeFileSync(path.join(directory, "host-result.json"), json(result) + "\n", "utf8");
    await group.goalNotice;
    if (group.notificationError) throw new Error(group.notificationError);
    active = null;
    if (end === "deadline" || end === "step-budget") throw new Error(name + " exceeded its test budget");
    return result;
  }

  const timer = setInterval(async () => {
    if (initiated) return;
    try {
      const preset = (await ctx.agentPresets.list()).find(row => row.id === presetId);
      if (!preset) return;
      initiated = true;
      if (preset.broken) throw new Error("building-loop preset is broken");
      if (process.env.BUILDING_LOOP_GOV_PROBE === "1") {
        finished(await runGroup("reuse", true));
        return;
      }
      const info = await ctx.llm.resolveModelInfo(route.provider, route.model);
      progress({ event: "route-ready", provider: route.provider, model: route.model, title: info?.name });
      const reuse = await runGroup(process.env.BUILDING_LOOP_GROUP ?? "reuse");
      if (reuse.steps === 0) throw new Error("No model step ran in the first arm");
      finished({ status: "observed", groups: [reuse] });
    } catch (error) {
      initiated = true;
      progress({ event: "error", error: String(error) });
      finished({ status: "error", error: String(error) });
    }
  }, 300);
  ctx.on("dispose", () => clearInterval(timer));
}
